class LargeObject {
    char data[1024 * 1024]; // 1MB object
public:
    ~LargeObject() { std::cout << "LargeObject destroyed.\n"; }
};

void demonstrate_lag() {
    std::weak_ptr<LargeObject> wp;
    {
        // Memory for LargeObject and control block is allocated here.
        auto sp = std::make_shared<LargeObject>();
        wp = sp; // weak_ptr now observes the object.

        // At end of this scope, sp is destroyed.
        // Strong count becomes 0, weak count is 1.
    }
    // "LargeObject destroyed." is printed here.
    // The object's destructor has run.
    // HOWEVER, the 1MB of memory is still allocated because wp exists.

    if (wp.expired()) {
        std::cout << "Object is expired, but memory is held.\n";
    }

    // Only when wp goes out of scope is the memory finally deallocated.
}
// At end of demonstrate_lag, wp is destroyed, weak count becomes 0, memory is freed.
